from collections import defaultdict
from math import factorial

MOD = 998244353

def multinvmod(k, m):
    """Compute the modular multiplicative inverse of k modulo m"""
    return pow(k, m - 2, m)

def binommod(a, b, m):
    """Compute a choose b modulo m"""
    if b > a:
        return 0
    return 1 if (x := factorial(b)) % m == 0 else factorial(m) % m * pow(x, -1, m) % m

def count_same(patterns, n):
    """Count the number of valid orderings with at least one singer in a specific position"""
    count = [1] * (n+1)
    for p in patterns:
        count[p[1]] -= 1
    return count[n]

def count_strongly_same(patterns, n):
    """Count the number of valid orderings exactly at each position"""
    match, mismatch = map(defaultdict, ([] for _ in range(n+1)))
    for p in patterns:
        match1, mismatch1 = tuple(sorted(p)),
        for i in range(1, n + 1):
            while mismatch1 and mismatch1[0] <= i:
                match1.pop(0), mismatch1.pop(0)
            if len(match1) == len(p):
                break
            match1.add(i), mismatch1.append(i)
    for i, (_, index) in enumerate(patterns):
        if match[index] == len(p):
            match[i] = 1, 0
        elif mismatch[index] == len(p):
            match[i] = 0, 1
        else:
            return 0
    return 2 ** len(patterns) % MOD

def solve(n, m, patterns):
    pattern = defaultdict(list)
    same = defaultdict(list)
    for one, (*group) in patterns:
        pattern[one].extend(group)
        same[one].append(group)
    res = multinvmod(2, MOD)
    for _, code in same.items():
        res *= binommod(len(code), len(patterns), MOD)
        res %= MOD
    for group in pattern.values():
        res *= invoke(group)
        res %= MOD
    return res

