from collections import defaultdict, deque

def merge_caterpillar():
    n, m = map(int, input().split())
    graph = defaultdict(set)
    merged_vertices = set()
    total_edges = 0

    for _ in range(m):
        a, b = map(int, input().split())
        graph[a].add(b)
        graph[b].add(a)
        total_edges += 1

    # Topological sort to find vertices that cannot be merged directly
    vertices = deque([v for v in range(1, n + 1) if len(graph[v]) in (0, 1)])
    if total_edges == 0: 
        return 0  # If there are no edges, no vertex can be merged

    while vertices:
        current = vertices.popleft()
        if len(graph[current]) == 0:
            merged_vertices |= {current}
        for neighbor in graph[current]:
            graph[neighbor].remove(current)
            if len(graph[neighbor]) == 1:
                vertices.append(neighbor)
        del graph[current]

    # If total_edges is not 2 * |merged_vertices|, a merging is needed
    if total_edges != 2 * len(merged_vertices):
        print(2 - len(merged_vertices))
    else:
        print(1)

