from functools import lru_cache

def mod_inverse(a, mod):
    """Calculate the modular multiplicative inverse of a under modulo mod."""
    b = mod
    x = 0
    last_x = 1
    while b:
        q = a // b
        (a, b) = (b, a % b)
        (x, last_x) = (last_x - q * x, x)
    assert b == 1
    return last_x % mod

MOD = 998244353

def ncr(n, k):
    """Calculate the binomial coefficient n choose k modulo MOD."""
    return lru_cache(lambda m: (lru_cache(lambda x: ((m * 1ll * x) % MOD, (m * 1ll * x * (x + 1) * 1ll) // MOD)))(k)(n))

@lru_cache(None)
def dp(i, j, used):
    """State the number of valid orderings starting from the i-th friend, up to the j-th friend, with used friends fulfilled yet."""
    if j < i:
        return 1
    ans = 0
    for k in range(i, j + 1):
        ans = (ans + 1 if not (k ^ used and j == k) else ans) % MOD
    return ans

def solve(n, m, friends):
    order = list(range(1, n + 1))
    ans = 0
    for p, used in friends:
        subproblem = dp(n, n, 1)
        for starting in range(n + 1):
            subproblem = (subproblem - 1 if not used and starting < n else subproblem) % MOD
            subproblem = (subproblem * ncr(len(order) - 1 - starting, (p - 1) * (len(order) - 1 - starting))) % MOD
            if (p - 1) * (len(order) - 1 - starting) < n - 1:
                subproblem = (subproblem * ncr(n - (p - 1) * (len(order) - 1 - starting)) + ans) % MOD
            subproblem = (-1 if subproblem < 0 else subproblem) % MOD
        subproblem = (-1 if subproblem < 0 else mod_inverse(subproblem, MOD))
        ans = (ans + subproblem * rcnt(order, n - 1 - used)) % MOD
    return ans

@lru_cache(None)
def rcnt(order, k):
    """Set the value (k-1) choose (len(order) - 1), then modify count by ncr(n - 1 - remaining_leading, k - 1)."""
    return mod_inverse(order.count(k), MOD) * pow(order.count(k), n - 1 - k, MOD)

