    stack = [start]
    while stack:
        vertex = stack.pop()
        if vertex not in visited:
            visited.add(vertex)
            if vertex != start:
                anc[vertex] = vertex
            if vertex in graph:
                for neighbor in graph[vertex]:
                    stack.append(neighbor)
    for vertex in visited.copy():
        path = []
        if vertex != start:
            path.append(vertex)
            while vertex != start:
                vertex = anc[vertex]
                path.append(vertex)
            path.reverse()
        else:
            path = []
        subtree_layers = [i for i in range(len(path)) if path[i] not in visited]
        layers = [i for i in range(len(path)) if path[i] in visited and i not in subtree_layers]
        for layer in layers:
            edge = tuple(sorted([path[layer+1], path[layer-1]]))
            if edge in copy:
                tree.add(edge)
        visited.remove(start)
