# Function to find the minimum number of merging operations required to make the graph a caterpillar
def min_operations_to_caterpillar(graph):
    vertices = {}
    paths = []
    paths_endpoints = []
    graph_adjacency_list = [[] for _ in range(n)]

    for v in range(n):
        for next_v in graph[v]:
            graph_adjacency_list[next_v].append(v)

    # Initialize paths and endpoints
    for v in range(n):
        if len(graph[v]) % 2 == 0:
            paths.append((v, v + 1))
        else:
            paths.append((v, v + 1))

    for i in range(n):
        if len(graph_adjacency_list[i]) > 1:
            if len(graph_adjacency_list[i]) % 2 == 0:
                paths_endpoints.append((i, i + 1))
            else:
                if i not in [0, 1]:  # Skip the endpoints
                    paths_endpoints.append((i, i + 1))

    # Transform paths and endpoint nodes into caterpillar form
    for path_start, path_end in paths:
        if (path_end - path_start) > 1:
            paths.remove((path_start, path_end))
            paths.remove((path_end - path_start, path_end))
            paths.append((path_start, path_end - 2))
            paths.remove((path_end - 2, path_end))
            paths_endpoints.remove(
                (path_start + 2, path_end)
            )
            paths_endpoints.remove((path_start + 1, path_end))

    for i1, i2 in paths_endpoints:
        if (i2 - i1) > 1:
            paths.remove((i1 + 2, i2 - 1))
            paths_endpoints.remove((i1, i2))

    # Calculate the minimum number of operations
    operations = 0
    for path_start, path_end in paths:
        nodes_to_merge = 1
        for i in range(path_start, path_end):
            if i + 2 not in graph_adjacency_list[i]:
                nodes_to_merge += 1
        operations += nodes_to_merge

    return operations

