from collections import defaultdict

def find_set(parent, i):
    if parent[i] == i:
        return i
    return find_set(parent, parent[i])

def union(parent, rank, x, y):
    rootx = find_set(parent, x)
    rooty = find_set(parent, y)
    if rootx == rooty:
        return False
    if rank[rootx] < rank[rooty]:
        parent[rootx] = rooty
    elif rank[rooty] < rank[rootx]:
        parent[rooty] = rootx
    else:
        parent[rooty] = rootx
        rank[rootx] += 1
    return True

def find_min_caterpillar_merges(n, m, edges):
    parent, rank = defaultdict(int), defaultdict(int)
    for i in range(n):
        parent[i] = i
    for u, v in edges:
        if not union(parent, rank, u, v) and not union(parent, rank, v, u):
            return -1
    return n - 1

