def min_reversals(a, b):
    n = len(a)
    if n % 2 == 1:
        return -1
    reverse_count = 0
    p = 0
    while p < n:
        if a[p:n-p] != b[p:n-p][::-1]:
            reverse_count += 1
            if reverse_count > n:
                return -1
            a = a[::-1][:p] + a[n-p:p] + a[n-p:]
        p += 2
    return reverse_count, p

